// Normaliza el correo y construye la petición para la API de Anthropic.
const remitente = $json.From || $json.from || 'desconocido';
const asunto = $json.Subject || $json.subject || '(sin asunto)';
const cuerpo = ($json.snippet || $json.text || '').slice(0, 2000);

const sistema = 'Eres el asistente de triaje de un buzon profesional en espanol. ' +
  'Devuelve SOLO un JSON valido con estas claves: ' +
  'categoria (consulta | pedido | incidencia | factura | comercial | spam | revisar), ' +
  'urgencia (alta | media | baja), ' +
  'resumen (maximo 2 frases), ' +
  'respuesta (borrador de respuesta cordial y breve en espanol, tuteo, listo para revisar; ' +
  'si el correo es una reclamacion o un tema legal, la respuesta es solo un acuse de recibo). ' +
  'Nada de texto fuera del JSON.';

const payload = {
  model: 'claude-haiku-4-5',
  max_tokens: 700,
  system: sistema,
  messages: [ { role: 'user', content: 'Remitente: ' + remitente + '\nAsunto: ' + asunto + '\nMensaje:\n' + cuerpo } ]
};

return [ { json: { payload: payload, remitente: remitente, asunto: asunto } } ];

// Extrae el JSON que devuelve Claude y lo une a los datos del correo.
const origen = $('Preparar petición IA').first().json;
const bruto = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text : '';
const limpio = bruto.replace(/```json/g, '').replace(/```/g, '').trim();

let datos;
try {
  datos = JSON.parse(limpio);
} catch (e) {
  // Si la IA no devolvio JSON valido, el correo se marca para revision manual.
  datos = { categoria: 'revisar', urgencia: 'media', resumen: bruto.slice(0, 300), respuesta: '' };
}

return [ { json: {
  remitente: origen.remitente,
  asunto: origen.asunto,
  categoria: datos.categoria || 'revisar',
  urgencia: datos.urgencia || 'media',
  resumen: datos.resumen || '(sin resumen)',
  respuesta: datos.respuesta || 'Gracias por tu mensaje. Lo hemos recibido y te respondemos en breve.'
} } ];

